            @Override public RenderType getFrameRenderType() { return CustomRenderTypes.BOSS_BAR; }  // 边框着色器/渲染类型（null 则跳过）
            @Override public RenderType getFillRenderType() { return CustomRenderTypes.BOSS_BAR; }  // 填充着色器/渲染类型（null 则跳过），可使用不同的预设
            @Override public int getFrameWidth() { return 420; }  // 边框像素宽度（RenderType-only 模式需要此项，纹理模式自动检测）
            @Override public int getFrameHeight() { return 40; }  // 边框像素高度
            @Override public int getFillWidth() { return 400; }  // 填充像素宽度（RenderType-only 模式需要此项，纹理模式自动检测）
            @Override public int getFillHeight() { return 30; }  // 填充像素高度
            @Override public int getFrameOffsetX() { return 0; }  // 边框 X 偏移
            @Override public int getFrameOffsetY() { return -10; }  // 边框 Y 偏移
            @Override public int getFillOffsetX() { return 0; }  // 填充 X 偏移
            @Override public int getFillOffsetY() { return 0; }  // 填充 Y 偏移
            @Override public float getAlpha() { return 1.0f; }  // 整体 Boss 血条透明度，0.0~1.0（默认 1.0）
        };
    }

    // 实体额外渲染层
    @Override
    public EntityLayerExtension entityLayerExtension() {
        return new EntityLayerExtension() {
            @Override public boolean enabled() { return true; }  // 启用渲染层
            @Override public RenderType getRenderType() { return CustomRenderTypes.BOSS_LAYER; }  // 渲染层着色器/渲染类型
            @Override public boolean isGlow() { return true; }  // 额外渲染层发光
            @Override public boolean isHurtOverlay() { return true; }  // 在此层显示受伤覆盖效果
