        };
    }

    // 全局迷雾
    @Override
    public GlobalFogExtension globalFogExtension() {
        return new GlobalFogExtension() {
            @Override public boolean enabled() { return true; }  // 启用迷雾
            @Override public boolean globalMode() { return true; }  // 全局模式（忽略半径，在维度内始终激活）
            @Override public float radius() { return 8.0f; }  // 实体周围的迷雾激活半径
            @Override public int fogColor() { return 0x000000; }  // 迷雾颜色为打包的 RGB int（例如 0xFF0000 = 红色，0x800080 = 紫色，0x000000 = 黑色）。若要混合自定义颜色，请覆盖 fogRed/Green/Blue()。
            @Override public float terrainFogStart(float renderDistance) { return renderDistance * 0.02f; }  // 地形迷雾起始距离
