            @Override public float size() { return 100.0f; }  // 天穹四边形大小
            @Override public float textureUvScale() { return 16.0f; }  // 纹理 UV 缩放
            @Override public float textureRed() { return 1.0f; }  // 纹理颜色红色分量（0.0 ~ 1.0）
            @Override public float textureGreen() { return 1.0f; }  // 纹理颜色绿色分量（0.0 ~ 1.0）
            @Override public float textureBlue() { return 1.0f; }  // 纹理颜色蓝色分量（0.0 ~ 1.0）
        };
    }

    // 全局战斗音乐
    @Override
    public CombatMusicExtension combatMusicExtension() {
        return new CombatMusicExtension() {
            @Override public boolean enabled() { return true; }  // 启用战斗音乐
            @Override public ResourceLocation soundEventId() { return sound("music.boss_battle"); }  // 音效事件 ID（必须在 sounds.json 中注册）
            @Override public SoundSource soundSource() { return SoundSource.MUSIC; }  // 音效类别
            @Override public float volume() { return 1.0f; }  // 播放音量（0.0 ~ 1.0）
            @Override public float pitch() { return 1.0f; }  // 播放音调
            @Override public boolean loop() { return true; }  // 循环播放
            @Override public boolean strictMusicLock() { return true; }  // 激活时阻止所有其他 MUSIC 音效
        };
    }

    // 条件门控：迷雾/天穹/音乐仅在对应的 shouldEnableXxx 返回 true 时激活；约每秒针对维度的主实体重新检查一次
    @Override
    public boolean shouldEnableFog(LivingEntity entity) {
        return entity.getHealth() < entity.getMaxHealth() * 0.5f;  // 示例：当实体生命值低于 50% 时激活迷雾
    }

    @Override
    public boolean shouldEnableSkybox(LivingEntity entity) {
        return true;  // 每个实体实例的天穹激活条件
    }

    @Override
    public boolean shouldEnableMusic(LivingEntity entity) {
        return true;  // 每个实体实例的战斗音乐激活条件
    }

    /*
     * 条件切换 — 覆盖实体感知的重载方法（在所有五个扩展方法上：bossBar / entityLayer / globalFog /
     * globalSkybox / combatMusic）以根据实体状态返回不同的扩展对象。ECA 仅在传入非 null 实体时调用实体感知重载
     * （其他情况使用无参变体），并捕获其抛出的任何异常，回退至无参变体。
     * 全局效果约每秒针对维度的主实体重新评估；实例效果（Boss 血条/渲染层）每帧重新评估。
     */
    @Override
    public GlobalSkyboxExtension globalSkyboxExtension(LivingEntity entity) {
        if (entity.getHealth() < entity.getMaxHealth() * 0.5f) {
            return phase2Skybox;  // 生命值低于 50%：切换至你定义的另一个 GlobalSkyboxExtension
        }
        return globalSkyboxExtension();  // 默认：使用上方的无参天穹
    }
}
